WITH cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), event_time) / 30 AS months_since_event_time, TRIM(event_type) AS clean_event_type FROM web_events WHERE event_time >= TIMESTAMP '2023-09-30 10:00:00' AND session_id IN (3, 7, 31, 34)), gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM cleaned), sessionized AS (SELECT id, session_id, event_type, event_time, duration_sec, months_since_event_time, SUM(is_new_burst) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT burst_id, CASE WHEN duration_sec >= 374 THEN 'HIGH' ELSE 'LOW' END AS duration_sec_tier, MIN(event_time) AS first_event_time, ROUND(SUM(months_since_event_time) / NULLIF(COUNT(CASE WHEN event_type = 'click' THEN 1 END), 0), 2) AS months_since_event_time_per_click FROM sessionized GROUP BY CUBE (burst_id, CASE WHEN duration_sec >= 374 THEN 'HIGH' ELSE 'LOW' END) ORDER BY duration_sec_tier DESC NULLS LAST
